const STORAGE_KEY = 'runway-styling-bag-v3';

// Bag State Sync
function getBag() {
  try {
    const raw = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (Array.isArray(raw)) return { items: raw };
    if (raw && Array.isArray(raw.items)) return raw;
    return { items: [] };
  } catch (_) {
    return { items: [] };
  }
}

function saveBag(bag) {
  const arr = Array.isArray(bag) ? bag : (bag.items || []);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(arr));
  updateCartCount();
}

function updateCartCount() {
  const b = getBag();
  const items = Array.isArray(b) ? b : (b.items || []);
  const count = items.reduce((s, it) => s + (it.quantity || 1), 0);
  document.querySelectorAll('[data-cart-count]').forEach(el => el.textContent = count);
}
updateCartCount();

function showToast(msg) {
  const t = document.getElementById('toast-status');
  if (!t) return;
  t.textContent = msg;
  t.classList.add('is-on');
  setTimeout(() => t.classList.remove('is-on'), 2600);
}

