// Add to Bag from Card
document.querySelectorAll('.col-add-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const card = btn.closest('.col-product-card');
    const pid = btn.dataset.prodId;
    const prod = CATALOG[pid];
    if (!prod) return;

    const activePill = card.querySelector('.col-size-pill.is-active');
    const size = activePill ? activePill.dataset.size : 'M';

    const bag = getBag();
    const existing = bag.items.find(x => x.id === pid && x.size === size);
    if (existing) {
      existing.quantity = (existing.quantity || 1) + 1;
    } else {
      bag.items.push({
        id: pid,
        name: prod.title,
        price: prod.price,
        priceNum: prod.priceNum,
        image: prod.image,
        size: size,
        quantity: 1
      });
    }
    saveBag(bag);
    showToast('✓ Added ' + prod.title + ' (' + size + ') to your Nexus cart!');

    btn.innerHTML = '<span>ADDED ✓</span>';
    setTimeout(() => {
